// FILE: frontend/src/utils/samplingUtils.js
//
// --- VERSION 0.1.0 ---
// Utility for evenly sampling down an array of points to a maximum length.
// Returns the original array if it's already <= maxPoints.

export function sampleData(data, maxPoints) {
  if (!Array.isArray(data) || data.length <= maxPoints) {
    return data;
  }
  const stride = Math.ceil(data.length / maxPoints);
  return data.filter((_, idx) => idx % stride === 0);
}
